-- Additive marketplace migration. Legacy receipts, science, funds and history
-- are never rewritten. Money is a canonical decimal string, not SQLite REAL.
CREATE TABLE IF NOT EXISTS market_migrations(version INTEGER PRIMARY KEY, applied_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS brain_projects(id TEXT PRIMARY KEY, slug TEXT NOT NULL UNIQUE, code TEXT NOT NULL UNIQUE, spec_root TEXT NOT NULL, spec TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'proposed', created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS market_products(id TEXT PRIMARY KEY, slug TEXT NOT NULL UNIQUE, definition TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS project_generations(id TEXT PRIMARY KEY, project_id TEXT NOT NULL REFERENCES brain_projects(id), manifest_root TEXT NOT NULL UNIQUE, manifest TEXT NOT NULL, status TEXT NOT NULL, budget_atoms TEXT NOT NULL, reserved_atoms TEXT NOT NULL DEFAULT '0', accepted_atoms TEXT NOT NULL DEFAULT '0', paid_atoms TEXT NOT NULL DEFAULT '0', verification_budget_atoms TEXT NOT NULL, created_at INTEGER NOT NULL, closed_at INTEGER);
CREATE TABLE IF NOT EXISTS project_task_links(project_id TEXT NOT NULL REFERENCES brain_projects(id), generation_id TEXT NOT NULL REFERENCES project_generations(id), scientific_task_id TEXT NOT NULL, PRIMARY KEY(project_id,generation_id,scientific_task_id));
CREATE TABLE IF NOT EXISTS work_packages(id TEXT PRIMARY KEY, semantic_id TEXT NOT NULL, generation_id TEXT NOT NULL REFERENCES project_generations(id), kind TEXT NOT NULL, spec TEXT NOT NULL, budget_atoms TEXT NOT NULL, credit_units TEXT NOT NULL, status TEXT NOT NULL, max_attempts INTEGER NOT NULL, attempts INTEGER NOT NULL DEFAULT 0, UNIQUE(generation_id,semantic_id,kind));
CREATE TABLE IF NOT EXISTS work_assignments(id TEXT PRIMARY KEY, work_id TEXT NOT NULL REFERENCES work_packages(id), actor TEXT NOT NULL, source TEXT NOT NULL, session_id TEXT NOT NULL, attempt INTEGER NOT NULL, fence INTEGER NOT NULL, status TEXT NOT NULL, lease_until INTEGER NOT NULL, wall_until INTEGER NOT NULL, progress_sequence INTEGER NOT NULL DEFAULT 0, completed_units INTEGER NOT NULL DEFAULT 0, commitment TEXT, result_root TEXT, created_at INTEGER NOT NULL, UNIQUE(work_id,attempt));
CREATE UNIQUE INDEX IF NOT EXISTS one_live_work_assignment ON work_assignments(work_id) WHERE status IN ('assigned','running','submitted','verifying');
CREATE INDEX IF NOT EXISTS work_actor_live ON work_assignments(actor,status,lease_until);
CREATE TABLE IF NOT EXISTS work_progress_events(assignment_id TEXT NOT NULL REFERENCES work_assignments(id), sequence INTEGER NOT NULL, completed_units INTEGER NOT NULL, evidence_root TEXT NOT NULL, created_at INTEGER NOT NULL, PRIMARY KEY(assignment_id,sequence));
CREATE TABLE IF NOT EXISTS market_artifacts(root TEXT PRIMARY KEY, schema TEXT NOT NULL, bytes INTEGER NOT NULL, storage_mode TEXT NOT NULL, manifest TEXT NOT NULL, status TEXT NOT NULL, retained_until INTEGER NOT NULL, deposit_owner TEXT, close_authority TEXT);
CREATE TABLE IF NOT EXISTS market_artifact_references(artifact_root TEXT NOT NULL REFERENCES market_artifacts(root), owner_type TEXT NOT NULL, owner_id TEXT NOT NULL, PRIMARY KEY(artifact_root,owner_type,owner_id));
CREATE TABLE IF NOT EXISTS work_acceptances(id TEXT PRIMARY KEY, semantic_id TEXT NOT NULL, work_id TEXT NOT NULL REFERENCES work_packages(id), assignment_id TEXT NOT NULL UNIQUE REFERENCES work_assignments(id), entitlement_id TEXT NOT NULL, beneficiary TEXT NOT NULL, correct_execution INTEGER NOT NULL, reward_eligible INTEGER NOT NULL, artifact_accepted INTEGER NOT NULL, artifact_root TEXT NOT NULL, evidence TEXT NOT NULL, reward_atoms TEXT NOT NULL, credit_units TEXT NOT NULL, accepted_at INTEGER NOT NULL, UNIQUE(semantic_id,work_id));
CREATE TABLE IF NOT EXISTS model_versions(id TEXT PRIMARY KEY, model_id TEXT NOT NULL REFERENCES market_products(id), project_id TEXT NOT NULL REFERENCES brain_projects(id), generation_id TEXT REFERENCES project_generations(id), manifest_root TEXT NOT NULL UNIQUE, manifest TEXT NOT NULL, status TEXT NOT NULL, created_at INTEGER NOT NULL, release_certificate TEXT);
CREATE TABLE IF NOT EXISTS model_artifacts(version_id TEXT NOT NULL REFERENCES model_versions(id), artifact_root TEXT NOT NULL REFERENCES market_artifacts(root), role TEXT NOT NULL, PRIMARY KEY(version_id,role));
CREATE TABLE IF NOT EXISTS model_evaluations(id TEXT PRIMARY KEY, version_id TEXT NOT NULL REFERENCES model_versions(id), evidence_root TEXT NOT NULL UNIQUE, report TEXT NOT NULL, accepted INTEGER NOT NULL, created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS model_contribution_manifests(version_id TEXT NOT NULL REFERENCES model_versions(id), entitlement_id TEXT NOT NULL, beneficiary TEXT NOT NULL, units TEXT NOT NULL, acceptance_ids TEXT NOT NULL, PRIMARY KEY(version_id,entitlement_id));
CREATE TABLE IF NOT EXISTS market_deployments(id TEXT PRIMARY KEY, version_id TEXT NOT NULL REFERENCES model_versions(id), runtime_root TEXT NOT NULL, status TEXT NOT NULL, capacity TEXT NOT NULL, heartbeat INTEGER, lease_fence INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS service_skus(id TEXT PRIMARY KEY, model_id TEXT NOT NULL REFERENCES market_products(id), spec TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS price_policies(id TEXT PRIMARY KEY, sku_id TEXT NOT NULL REFERENCES service_skus(id), version_id TEXT REFERENCES model_versions(id), policy TEXT NOT NULL, state TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS customer_accounts(id TEXT PRIMARY KEY, wallet TEXT NOT NULL UNIQUE, asset_id TEXT NOT NULL, available_atoms TEXT NOT NULL DEFAULT '0', reserved_atoms TEXT NOT NULL DEFAULT '0', consumed_atoms TEXT NOT NULL DEFAULT '0', refund_pending_atoms TEXT NOT NULL DEFAULT '0', refunded_atoms TEXT NOT NULL DEFAULT '0', created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS market_auth_challenges(id TEXT PRIMARY KEY, wallet TEXT NOT NULL, purpose TEXT NOT NULL, nonce TEXT NOT NULL UNIQUE, expires INTEGER NOT NULL, consumed INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS api_keys(id TEXT PRIMARY KEY, customer_id TEXT NOT NULL REFERENCES customer_accounts(id), verifier TEXT NOT NULL UNIQUE, allowance_id TEXT NOT NULL, scopes TEXT NOT NULL, expires INTEGER NOT NULL, revoked INTEGER NOT NULL DEFAULT 0, created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS fly_purchase_intents(id TEXT PRIMARY KEY, customer_id TEXT NOT NULL, payload_root TEXT NOT NULL, payload TEXT NOT NULL, state TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS fly_deposit_intents(id TEXT PRIMARY KEY, customer_id TEXT NOT NULL REFERENCES customer_accounts(id), asset_id TEXT NOT NULL, amount_atoms TEXT NOT NULL, chain_sequence INTEGER NOT NULL, state TEXT NOT NULL, finalized_signature TEXT, created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS spending_allowances(id TEXT PRIMARY KEY, customer_id TEXT NOT NULL REFERENCES customer_accounts(id), asset_id TEXT NOT NULL, policy TEXT NOT NULL, maximum_atoms TEXT NOT NULL, consumed_atoms TEXT NOT NULL DEFAULT '0', reserved_atoms TEXT NOT NULL DEFAULT '0', sequence INTEGER NOT NULL DEFAULT 0, expires INTEGER NOT NULL, revoked INTEGER NOT NULL DEFAULT 0, created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS service_quotes(id TEXT PRIMARY KEY, customer_id TEXT NOT NULL REFERENCES customer_accounts(id), version_id TEXT NOT NULL REFERENCES model_versions(id), sku_id TEXT NOT NULL REFERENCES service_skus(id), request_root TEXT NOT NULL, private_input TEXT NOT NULL, policy_id TEXT NOT NULL REFERENCES price_policies(id), amount_atoms TEXT NOT NULL, quote TEXT NOT NULL, expires INTEGER NOT NULL, created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS service_jobs(id TEXT PRIMARY KEY, customer_id TEXT NOT NULL REFERENCES customer_accounts(id), idempotency_key TEXT NOT NULL, request_root TEXT NOT NULL, quote_id TEXT NOT NULL UNIQUE REFERENCES service_quotes(id), version_id TEXT NOT NULL REFERENCES model_versions(id), allowance_id TEXT NOT NULL REFERENCES spending_allowances(id), status TEXT NOT NULL, settlement_status TEXT NOT NULL, reconciliation_status TEXT NOT NULL, amount_atoms TEXT NOT NULL, execution_kind TEXT, fence INTEGER NOT NULL DEFAULT 0, worker TEXT, lease_until INTEGER, progress INTEGER NOT NULL DEFAULT 0, output_root TEXT, receipt_id TEXT, error_code TEXT, created_at INTEGER NOT NULL, completed_at INTEGER, UNIQUE(customer_id,idempotency_key));
CREATE INDEX IF NOT EXISTS service_job_queue ON service_jobs(status,created_at);
CREATE TABLE IF NOT EXISTS market_job_events(id INTEGER PRIMARY KEY AUTOINCREMENT, job_id TEXT NOT NULL REFERENCES service_jobs(id), status TEXT NOT NULL, public_progress TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS usage_receipts(id TEXT PRIMARY KEY, job_id TEXT NOT NULL UNIQUE REFERENCES service_jobs(id), version_id TEXT NOT NULL, customer_id TEXT NOT NULL, receipt TEXT NOT NULL, signature TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS refund_intents(id TEXT PRIMARY KEY, customer_id TEXT NOT NULL, original_intent_id TEXT NOT NULL, amount_atoms TEXT NOT NULL, state TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS revenue_epochs(id TEXT PRIMARY KEY, version_id TEXT NOT NULL REFERENCES model_versions(id), receipt_id TEXT NOT NULL UNIQUE REFERENCES usage_receipts(id), asset_id TEXT NOT NULL, consumed_atoms TEXT NOT NULL, refunded_atoms TEXT NOT NULL, reserve_atoms TEXT NOT NULL, matured_atoms TEXT NOT NULL, state TEXT NOT NULL, chain_intent TEXT NOT NULL UNIQUE, created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS market_revenue_accumulators(version_id TEXT NOT NULL REFERENCES model_versions(id), asset_id TEXT NOT NULL, totals TEXT NOT NULL, PRIMARY KEY(version_id,asset_id));
CREATE TABLE IF NOT EXISTS revenue_allocations(id TEXT PRIMARY KEY, epoch_id TEXT NOT NULL REFERENCES revenue_epochs(id), pool TEXT NOT NULL, payee_id TEXT NOT NULL, amount_atoms TEXT NOT NULL, paid_atoms TEXT NOT NULL DEFAULT '0', state TEXT NOT NULL, UNIQUE(epoch_id,pool,payee_id));
CREATE TABLE IF NOT EXISTS claim_observations(id TEXT PRIMARY KEY, version_id TEXT NOT NULL, entitlement_id TEXT NOT NULL, asset_id TEXT NOT NULL, cumulative_claimed_atoms TEXT NOT NULL, beneficiary TEXT NOT NULL, source TEXT NOT NULL, observed_at INTEGER NOT NULL, UNIQUE(version_id,entitlement_id,asset_id,id));
CREATE TABLE IF NOT EXISTS market_claim_states(version_id TEXT NOT NULL, entitlement_id TEXT NOT NULL, asset_id TEXT NOT NULL, claimed_atoms TEXT NOT NULL DEFAULT '0', pending_atoms TEXT NOT NULL DEFAULT '0', beneficiary TEXT NOT NULL, beneficiary_sequence INTEGER NOT NULL DEFAULT 0, PRIMARY KEY(version_id,entitlement_id,asset_id));
CREATE TABLE IF NOT EXISTS market_settlement_outbox(id TEXT PRIMARY KEY, business_id TEXT NOT NULL UNIQUE, purpose TEXT NOT NULL, payload TEXT NOT NULL, status TEXT NOT NULL, transaction_signature TEXT, transaction_hash TEXT, blockhash TEXT, last_valid_block_height INTEGER, observed_height INTEGER, created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS market_chain_observations(id TEXT PRIMARY KEY, business_id TEXT NOT NULL, location TEXT NOT NULL UNIQUE, raw_root TEXT NOT NULL, envelope TEXT NOT NULL, status TEXT NOT NULL, observed_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS market_public_events(id INTEGER PRIMARY KEY AUTOINCREMENT, kind TEXT NOT NULL, object_id TEXT NOT NULL, public_data TEXT NOT NULL, created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS market_signed_requests(actor TEXT NOT NULL, action TEXT NOT NULL, request_id TEXT NOT NULL, request_root TEXT NOT NULL, result TEXT NOT NULL, created_at INTEGER NOT NULL, PRIMARY KEY(actor,action,request_id));
CREATE TRIGGER IF NOT EXISTS frozen_market_version BEFORE UPDATE OF manifest_root,manifest ON model_versions WHEN OLD.status IN ('released','deprecated','retired') BEGIN SELECT RAISE(ABORT,'released model content is frozen'); END;
CREATE TRIGGER IF NOT EXISTS frozen_market_shares_update BEFORE UPDATE ON model_contribution_manifests WHEN EXISTS(SELECT 1 FROM model_versions WHERE id=OLD.version_id AND status IN ('released','deprecated','retired')) BEGIN SELECT RAISE(ABORT,'released shares are frozen'); END;
CREATE TRIGGER IF NOT EXISTS frozen_market_shares_delete BEFORE DELETE ON model_contribution_manifests WHEN EXISTS(SELECT 1 FROM model_versions WHERE id=OLD.version_id AND status IN ('released','deprecated','retired')) BEGIN SELECT RAISE(ABORT,'released shares are retained'); END;
CREATE TRIGGER IF NOT EXISTS immutable_market_acceptance BEFORE UPDATE ON work_acceptances BEGIN SELECT RAISE(ABORT,'append-only acceptance'); END;
CREATE TRIGGER IF NOT EXISTS immutable_usage_receipt BEFORE UPDATE ON usage_receipts BEGIN SELECT RAISE(ABORT,'immutable usage receipt'); END;
CREATE TRIGGER IF NOT EXISTS immutable_generation_manifest BEFORE UPDATE OF manifest_root,manifest ON project_generations BEGIN SELECT RAISE(ABORT,'accepted work contract is frozen'); END;
INSERT OR IGNORE INTO market_migrations VALUES(1,unixepoch());
